"""Regular-language objects for Eywa ``match`` constraints.

The concrete syntax accepted here is the campaign predicate pattern grammar:

    union    := seq ('|' seq)*
    seq      := atom*
    atom     := primary '*'*
    primary  := literal | '(' union ')' | '[' item+ ']'
    item     := classchar ( '-' classchar )?

``\\`` escapes the next character both inside and outside of a character class.
There are no anchors, no dot wildcard, no ``+``/``?``, no negated classes and no
numeric escapes.  Matching is full (whole value) membership over Latin-1 code
points; ranges are ASCII, so byte values outside a range never match it.

The objects double as an efficient matcher: the parsed expression is compiled
into a Thompson NFA whose character transitions are 256+ bit masks, and the NFA
is simulated lazily as a DFA keyed on (state-set, character).  That keeps even
deeply nested repetition linear in the length of the value.
"""

from typing import List

__all__ = [
    'Regex', 'Empty', 'Range', 'Choice', 'Seq', 'Star', 'Matcher',
    'chars', 'text', 'choice', 'seq', 'star', 'plus', 'empty', 'parse',
    'ismatch', 'compile_pattern', 'RegexError',
]


class RegexError(Exception):
    """Raised for a malformed regular-language pattern."""


class Regex(object):
    """
    A regular expression.
    """

    __slots__ = ()

    def matches(self, s: str) -> bool:
        return Matcher(self).matches(s)


class Empty(Regex):
    """
    A regular expression that matches the empty string.
    """

    __slots__ = ()

    def __str__(self) -> str:
        return ""


class Range(Regex):
    """
    A regular expression that matches a character range.
    """

    __slots__ = ('low', 'high')

    def __init__(self, low: str, high: str):
        if len(low) != 1 or len(high) != 1:
            raise ValueError("Range must be single characters")
        self.low = low
        self.high = high

    def mask(self) -> int:
        low = ord(self.low)
        high = ord(self.high)
        if low > high:
            return 0
        return ((1 << (high - low + 1)) - 1) << low

    def __str__(self) -> str:
        if self.low == self.high:
            return _escape_out(self.low)
        return f'[{self.low}-{self.high}]'


class Choice(Regex):
    """
    A regular expression that matches a choice of regular expressions.
    """

    __slots__ = ('exprs',)

    def __init__(self, *args):
        self.exprs = tuple(args)

    def __str__(self) -> str:
        return f'({"|".join([str(e) for e in self.exprs])})'


class Seq(Regex):
    """
    A regular expression that matches a sequence of regular expressions.
    """

    __slots__ = ('exprs',)

    def __init__(self, *args):
        self.exprs = tuple(args)

    def __str__(self) -> str:
        return f'({"".join([str(e) for e in self.exprs])})'


class Star(Regex):
    """
    A regular expression that matches zero or more iterations of a regular expression.
    """

    __slots__ = ('expr',)

    def __init__(self, r: Regex):
        self.expr = r

    def __str__(self) -> str:
        return f'({str(self.expr)})*'


def _escape_out(ch: str) -> str:
    if ch in '()[]|*\\-':
        return '\\' + ch
    return ch


def chars(low: str, high: str) -> Regex:
    """
    A regular that matches a character range.
    """
    return Range(low, high)


def text(s: str) -> Regex:
    """
    A regular that matches an exact string.
    """
    if s == "":
        return empty()
    elif len(s) == 1:
        return chars(s, s)
    else:
        return seq(*[chars(c, c) for c in s])


def choice(*args) -> Regex:
    """
    A regular expression that matches a choice of regular expressions.
    """
    flat: List[Regex] = []
    for item in args:
        if isinstance(item, Choice):
            flat.extend(item.exprs)
        else:
            flat.append(item)
    if len(flat) == 0:
        return Empty()
    if len(flat) == 1:
        return flat[0]
    return Choice(*flat)


def seq(*args) -> Regex:
    """
    A regular expression that matches a sequence of regular expressions.
    """
    flat: List[Regex] = []
    for item in args:
        if isinstance(item, Empty):
            continue
        if isinstance(item, Seq):
            flat.extend(item.exprs)
        else:
            flat.append(item)
    if len(flat) == 0:
        return Empty()
    if len(flat) == 1:
        return flat[0]
    return Seq(*flat)


def star(r: Regex) -> Regex:
    """
    A regular expression that matches zero or more iterations of a regular expression.
    """
    if isinstance(r, Empty):
        return Empty()
    return Star(r)


def plus(r: Regex) -> Regex:
    """
    A regular expression that matches one or more iterations of a regular expression.
    """
    return seq(r, star(r))


def empty() -> Empty:
    """
    A regular expression that matches the empty string.
    """
    return Empty()


class _Parser(object):
    """Recursive-descent parser for the campaign pattern grammar."""

    __slots__ = ('s', 'i', 'n')

    def __init__(self, s: str):
        self.s = s
        self.i = 0
        self.n = len(s)

    def parse(self) -> Regex:
        node = self.parse_union()
        if self.i != self.n:
            # An unbalanced ')' is the only way to stop early; treat the rest
            # as literal text so that decoding never aborts a whole campaign.
            node = seq(node, self.parse_seq())
        return node

    def parse_union(self) -> Regex:
        alternatives = [self.parse_seq()]
        while self.i < self.n and self.s[self.i] == '|':
            self.i += 1
            alternatives.append(self.parse_seq())
        return choice(*alternatives)

    def parse_seq(self) -> Regex:
        items: List[Regex] = []
        while self.i < self.n:
            ch = self.s[self.i]
            if ch == '|' or ch == ')':
                break
            items.append(self.parse_atom())
        return seq(*items)

    def parse_atom(self) -> Regex:
        ch = self.s[self.i]
        if ch == '(':
            self.i += 1
            node = self.parse_union()
            if self.i < self.n and self.s[self.i] == ')':
                self.i += 1
        elif ch == '[':
            node = self.parse_class()
        elif ch == '\\':
            self.i += 1
            if self.i < self.n:
                literal = self.s[self.i]
                self.i += 1
            else:
                literal = '\\'
            node = chars(literal, literal)
        elif ch == '*':
            # A stray repetition symbol: accept it literally.
            self.i += 1
            node = chars('*', '*')
        else:
            self.i += 1
            node = chars(ch, ch)
        while self.i < self.n and self.s[self.i] == '*':
            self.i += 1
            node = star(node)
        return node

    def parse_class(self) -> Regex:
        self.i += 1  # consume '['
        items: List[Regex] = []
        while self.i < self.n and self.s[self.i] != ']':
            low = self._class_char()
            if (self.i + 1 < self.n and self.s[self.i] == '-'
                    and self.s[self.i + 1] != ']'):
                self.i += 1
                high = self._class_char()
            else:
                high = low
            items.append(chars(low, high))
        if self.i < self.n:
            self.i += 1  # consume ']'
        if not items:
            # An empty class matches nothing.
            return chars('\x01', '\x00')
        if len(items) == 1:
            return items[0]
        return Choice(*items)

    def _class_char(self) -> str:
        ch = self.s[self.i]
        if ch == '\\':
            self.i += 1
            if self.i < self.n:
                ch = self.s[self.i]
                self.i += 1
            else:
                ch = '\\'
        else:
            self.i += 1
        return ch


def parse(pattern: str) -> Regex:
    """Parse a campaign pattern into a regular-language object."""
    if not isinstance(pattern, str):
        raise RegexError('pattern must be a string')
    return _Parser(pattern).parse()


class _NFA(object):
    __slots__ = ('eps', 'char', 'count')

    def __init__(self):
        self.eps = []
        self.char = []
        self.count = 0

    def state(self) -> int:
        self.eps.append([])
        self.char.append([])
        index = self.count
        self.count += 1
        return index

    def link(self, source: int, target: int):
        self.eps[source].append(target)


class Matcher(Regex):
    """A compiled, cached regular-language membership test."""

    __slots__ = ('start', 'accept', 'edges', 'cache', 'pattern', '_limit')

    def __init__(self, root: Regex, pattern=None):
        nfa = _NFA()
        start, end = self._build(nfa, root)
        accept = nfa.state()
        nfa.link(end, accept)
        closures = [None] * nfa.count
        for index in range(nfa.count):
            if closures[index] is None:
                closures[index] = self._closure(nfa, index, closures)
        edges = []
        for index in range(nfa.count):
            edges.append([(mask, closures[target]) for (mask, target) in nfa.char[index]])
        self.start = closures[start]
        self.accept = 1 << accept
        self.edges = edges
        self.cache = {}
        self.pattern = pattern
        self._limit = 65536

    @staticmethod
    def _build(nfa: _NFA, node: Regex):
        if isinstance(node, Range):
            source = nfa.state()
            target = nfa.state()
            nfa.char[source].append((node.mask(), target))
            return source, target
        if isinstance(node, Empty):
            source = nfa.state()
            return source, source
        if isinstance(node, Star):
            source = nfa.state()
            sink = nfa.state()
            body_start, body_end = Matcher._build(nfa, node.expr)
            nfa.link(source, body_start)
            nfa.link(source, sink)
            nfa.link(body_end, body_start)
            nfa.link(body_end, sink)
            return source, sink
        if isinstance(node, Choice):
            source = nfa.state()
            sink = nfa.state()
            for item in node.exprs:
                item_start, item_end = Matcher._build(nfa, item)
                nfa.link(source, item_start)
                nfa.link(item_end, sink)
            return source, sink
        if isinstance(node, Seq):
            source = None
            sink = None
            for item in node.exprs:
                item_start, item_end = Matcher._build(nfa, item)
                if source is None:
                    source = item_start
                else:
                    nfa.link(sink, item_start)
                sink = item_end
            if source is None:
                source = nfa.state()
                sink = source
            return source, sink
        if isinstance(node, Matcher):
            raise RegexError('nested matcher')
        raise RegexError('unknown regular-language object')

    @staticmethod
    def _closure(nfa: _NFA, index: int, closures):
        seen = 1 << index
        stack = [index]
        while stack:
            current = stack.pop()
            for target in nfa.eps[current]:
                bit = 1 << target
                if not seen & bit:
                    seen |= bit
                    stack.append(target)
                    if closures[target] is not None:
                        seen |= closures[target]
        # Memoised closures are only complete once every reachable state has
        # been expanded; recompute cheaply with a worklist to be safe.
        changed = True
        while changed:
            changed = False
            bits = seen
            position = 0
            while bits:
                low = bits & -bits
                position = low.bit_length() - 1
                bits ^= low
                for target in nfa.eps[position]:
                    bit = 1 << target
                    if not seen & bit:
                        seen |= bit
                        changed = True
        for target_index in _bits(seen):
            if closures[target_index] is None or (closures[target_index] | seen) != closures[target_index]:
                closures[target_index] = seen
        return seen

    def _step(self, current: int, bit: int) -> int:
        result = 0
        edges = self.edges
        for index in _bits(current):
            for mask, closure in edges[index]:
                if mask & bit:
                    result |= closure
        return result

    def matches(self, s) -> bool:
        if not isinstance(s, str):
            return False
        current = self.start
        cache = self.cache
        if len(cache) > self._limit:
            cache.clear()
        for character in s:
            key = (current, character)
            following = cache.get(key)
            if following is None:
                following = self._step(current, 1 << ord(character))
                cache[key] = following
            current = following
            if not current:
                return False
        return bool(current & self.accept)

    def __str__(self) -> str:
        return "" if self.pattern is None else str(self.pattern)


def _bits(value: int):
    while value:
        low = value & -value
        yield low.bit_length() - 1
        value ^= low


_CACHE = {}


def compile_pattern(pattern: str) -> Matcher:
    """Compile (and cache) a pattern string into a membership matcher."""
    matcher = _CACHE.get(pattern)
    if matcher is None:
        matcher = Matcher(parse(pattern), pattern)
        if len(_CACHE) > 4096:
            _CACHE.clear()
        _CACHE[pattern] = matcher
    return matcher


def ismatch(r, s: str) -> bool:
    """
    Determine if a string matches a regular expression.
    """
    if isinstance(r, Matcher):
        return r.matches(s)
    if isinstance(r, str):
        return compile_pattern(r).matches(s)
    return Matcher(r).matches(s)
